const html = $input.first().json.data || '';
const byteLength = Buffer.byteLength(html, 'utf8');
const sub14kb = byteLength <= 14336;
const hasChunkId = html.includes('data-chunk-id');
const hasWikidata = html.includes('wikidata.org/wiki/Q');
return [{
  json: {
    byteLength,
    sub14kb,
    hasChunkId,
    hasWikidata,
    astTokens: Math.round(byteLength / 4),
    pass: sub14kb || hasChunkId
  }
}];

const item = $input.first().json;
const dlqEntry = {
  timestamp: new Date().toISOString(),
  eventId: 'DLQ-' + Date.now(),
  reason: item.error || 'TRIAGE_FAIL',
  status: 'NOT_MEASURED',
  payload: item
};
return [{ json: dlqEntry }];
